// The time zone, through a Date's local fields.
var instant = new Date(1577836800000);
module.exports = {
  hour: instant.getHours(),
  made: new Date(2020, 0, 1).getTime(),
  offset: instant.getTimezoneOffset(),
  text: String(instant).slice(0, 33),
  // Which members are objects is decided by the zone as much as a value is.
  utc: instant.getTimezoneOffset() === 0 ? { yes: true } : undefined,
  day: instant.toLocaleDateString("en-US"),
};
